package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {









    @Test
    public void test_value_InvalidValue() throws IOException {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123);
        jsonWriter.value("invalid value");
        try {
            jsonWriter.value(123.45);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was 123.45", e.getMessage());
        }
    }
